ontrolService.stop();\n279\t        actionSchedulerService.stop();\n280\t        await actionRunnerService.suspend();\n281\t        await agentRunnerService.stopAll();\n282\t        await trackEvent('electron_stop');\n283\t        await flush();\n284\t    } catch {\n285\t        // Shutdown cleanup must never block quit.\n286\t    } finally {\n287\t        clearTimeout(watchdog);\n288\t        app.quit();\n289\t    }\n290\t}\n291\t\n292\tfunction waitForRendererFlush(browserWindow, requestId) {\n293\t    if (browserWindow.webContents.isDestroyed()) return Promise.resolve();\n294\t\n295\t    return new Promise((resolve) => {\n296\t        let isSettled = false;\n297\t        let timeoutId = null;\n298\t\n299\t        function settle() {\n300\t            if (isSettled) return;\n301\t\n302\t            isSettled = true;\n303\t            if (timeoutId !== null) clearTimeout(timeoutId);\n304\t            ipcMain.removeListener(LIFECYCLE_FLUSH_DONE_CHANNEL, handleFlushDone);\n305\t            resolve();\n306\t        }\n307\t\n308\t        function handleFlushDone(event, completedRequestId) {\n309\t            if (event.sender !== browserWindow.webContents) return;\n310\t            if (completedRequestId !== requestId) return;\n311\t\n312\t            settle();\n313\t        }\n314\t\n315\t        timeoutId = setTimeout(settle, QUIT_FLUSH_TIMEOUT_MS);\n316\t        ipcMain.on(LIFECYCLE_FLUSH_DONE_CHANNEL, handleFlushDone);\n317\t\n318\t        try {\n319\t            browserWindow.webContents.send(LIFECYCLE_FLUSH_REQUEST_CHANNEL, requestId);\n320\t        } catch {\n321\t            settle();\n322\t        }\n323\t    });\n324\t}\n325\t\n326\tasync function flushRendererPendingCommits() {\n327\t    const windows = BrowserWindow.getAllWindows();\n328\t    const flushes = windows.map((browserWindow, index) => waitForRendererFlush(browserWindow, `quit-${Date.now()}-${index}`));\n329\t\n330\t    await Promise.all(flushes);\n331\t}\n332\t\n333\tapp.whenReady().then(async ()