import { register } from '../service_injector'

export type TelemetryRuntime = 'react_web' | 'react_electron'

export type TelemetryEventName =
    | 'complete_release'
    | 'create_card'
    | 'create_project'
    | 'external_file_import'
    | 'navigation'
    | 'open_project'
    | 'react_start'
    | 'react_stop'
    | 'remarkable_import'

interface AptabaseClient {
    init(appKey: string): void
    trackEvent(eventName: string, properties: Record<string, string>): Promise<void> | void
}

interface SentryClient {
    captureException(error: unknown): void
    flush(timeoutMs?: number): Promise<boolean>
    init(options: { dsn: string }): void
}

interface TelemetryClients {
    aptabase: AptabaseClient
    sentry: SentryClient
}

interface TelemetryInitOptions {
    aptabaseAppKey?: string
    clients: TelemetryClients
    runtime: TelemetryRuntime
    sentryDsn?: string
}

const FLUSH_TIMEOUT_MS = 1500
const TELEMETRY_EVENTS = new Set<TelemetryEventName>([
    'complete_release',
    'create_card',
    'create_project',
    'external_file_import',
    'navigation',
    'open_project',
    'react_start',
    'react_stop',
    'remarkable_import',
])

function hasValue(value: string | undefined) {
    return typeof value === 'string' && value.trim().length > 0
}

function settlePendingEvents(events: Promise<void>[]) {
    return Promise.all(events.map(async (event) => {
        try {
            await event
        } catch {
            // Telemetry must not affect application behavior.
        }
    }))
}

/** Owns React telemetry setup and keeps outbound usage payloads detail-free. */
export class TelemetryService {
    private aptabaseEnabled: boolean
    private clients: TelemetryClients | null
    private pendingEvents: Set<Promise<void>>
    private runtime: TelemetryRuntime
    private sentryEnabled: boolean

    constructor() {
        this.aptabaseEnabled = false
        this.clients = null
        this.pendingEvents = new Set()
        this.runtime = 'react_web'
        this.sentryEnabled = false
        register('telemetryService', this)
    }

    init(options: TelemetryInitOptions) {
        this.clients = options.clients
        this.runtime = options.runtime
        this.aptabaseEnabled = hasValue(options.aptabaseAppKey)
        this.sentryEnabled = hasValue(options.sentryDsn)

        if (this.sentryEnabled) {
            try {
                this.clients.sentry.init({ dsn: options.sentryDsn as string })
            } catch {
                this.sentryEnabled = false
            }
        }

        if (this.aptabaseEnabled) {
            try {
                this.clients.aptabase.init(options.aptabaseAppKey as string)
            } catch {
                this.aptabaseEnabled = false
            }
        }
    }

    trackEvent(eventName: TelemetryEventName) {
        if (!TELEMETRY_EVENTS.has(eventName)) throw new Error(`Unsupported telemetry event: ${eventName}`)
        if (!this.clients || !this.aptabaseEnabled) return

        try {
            const pendingEvent = Promise.resolve(this.clients.aptabase.trackEvent(eventName, { runtime: this.runtime }))
            this.pendingEvents.add(pendingEvent)
            pendingEvent.finally(() => this.pendingEvents.delete(pendingEvent))
        } catch {
            // Telemetry must not affect application behavior.
        }
    }

    captureError(error: unknown) {
        if (!this.clients || !this.sentryEnabled) return

        try {
            this.clients.sentry.captureException(error)
        } catch {
            // Telemetry must not affect application behavior.
        }
    }

    async flush(timeoutMs = FLUSH_TIMEOUT_MS) {
        const pendingEvents = [...this.pendingEvents]
        await Promise.race([
            settlePendingEvents(pendingEvents),
            new Promise<void>((resolve) => {
                window.setTimeout(resolve, timeoutMs)
            }),
        ])

        if (!this.clients || !this.sentryEnabled) return

        try {
            await this.clients.sentry.flush(timeoutMs)
        } catch {
            // Telemetry must not affect application behavior.
        }
    }
}

export const telemetryService = new TelemetryService()

import { init as initAptabase, trackEvent as trackAptabaseEvent } from '@aptabase/web'
import * as Sentry from '@sentry/react'
import { getElectronDataBridge } from '../../data/electron_data_bridge'
import { telemetryService, type TelemetryRuntime } from './telemetry_service'

let isReactTelemetryStarted = false

function getReactRuntime(): TelemetryRuntime {
    return getElectronDataBridge() ? 'react_electron' : 'react_web'
}

function getErrorPayload(event: ErrorEvent) {
    return event.error ?? new Error(event.message)
}

function getPromiseRejectionPayload(event: PromiseRejectionEvent) {
    return event.reason ?? new Error('Unhandled promise rejection')
}

function handleReactError(event: ErrorEvent) {
    telemetryService.captureError(getErrorPayload(event))
}

function handleReactPromiseRejection(event: PromiseRejectionEvent) {
    telemetryService.captureError(getPromiseRejectionPayload(event))
}

function handleReactStop() {
    telemetryService.trackEvent('react_stop')
    void telemetryService.flush()
}

/** Initializes React telemetry from app bootstrap code, not service module load. */
export function startReactTelemetry() {
    if (isReactTelemetryStarted) return

    isReactTelemetryStarted = true
    telemetryService.init({
        aptabaseAppKey: import.meta.env.APTABASE_APP_KEY,
        clients: {
            aptabase: { init: initAptabase, trackEvent: trackAptabaseEvent },
            sentry: { captureException: Sentry.captureException, flush: Sentry.flush, init: Sentry.init },
        },
        runtime: getReactRuntime(),
        sentryDsn: import.meta.env.PROD ? import.meta.env.SENTRY_DSN : undefined,
    })
    telemetryService.trackEvent('react_start')

    window.addEventListener('beforeunload', handleReactStop)
    window.addEventListener('error', handleReactError)
    window.addEventListener('unhandledrejection', handleReactPromiseRejection)
}

const FLUSH_TIMEOUT_MS = 1500;
const ELECTRON_RUNTIME = 'electron_main';
const TELEMETRY_EVENTS = new Set(['electron_starting', 'electron_stop']);

let aptabaseEnabled = false;
let aptabaseInitialize = null;
let aptabaseTrackEvent = null;
let pendingAptabaseEvents = new Set();
let sentry = null;
let sentryEnabled = false;

function hasValue(value) {
    return typeof value === 'string' && value.trim().length > 0;
}

function loadSentryClient() {
    try {
        return require('@sentry/electron/main');
    } catch {
        return null;
    }
}

function loadAptabaseClient() {
    try {
        return require('@aptabase/electron/main');
    } catch {
        return null;
    }
}

function rememberPendingEvent(event) {
    pendingAptabaseEvents.add(event);
    event.finally(() => pendingAptabaseEvents.delete(event));
}

async function settlePendingEvents(events) {
    await Promise.all(events.map(async (event) => {
        try {
            await event;
        } catch {
            // Telemetry must not affect desktop shutdown or startup.
        }
    }));
}

function trackEvent(eventName) {
    if (!TELEMETRY_EVENTS.has(eventName)) throw new Error(`Unsupported telemetry event: ${eventName}`);
    if (!aptabaseEnabled || !aptabaseTrackEvent) return Promise.resolve();

    try {
        const pendingEvent = Promise.resolve(aptabaseTrackEvent(eventName, { runtime: ELECTRON_RUNTIME }));
        rememberPendingEvent(pendingEvent);

        return pendingEvent.catch(() => undefined);
    } catch {
        return Promise.resolve();
    }
}

function captureError(error) {
    if (!sentryEnabled || !sentry) return;

    try {
        sentry.captureException(error);
    } catch {
        // Telemetry must not affect desktop behavior.
    }
}

async function flush(timeoutMs = FLUSH_TIMEOUT_MS) {
    const pendingEvents = [...pendingAptabaseEvents];
    await Promise.race([
        settlePendingEvents(pendingEvents),
        new Promise((resolve) => {
            setTimeout(resolve, timeoutMs);
        }),
    ]);

    if (!sentryEnabled || !sentry) return;

    try {
        await sentry.flush(timeoutMs);
    } catch {
        // Telemetry must not affect desktop shutdown.
    }
}

async function startElectronTelemetry(options = {}) {
    sentry = options.sentryClient ?? loadSentryClient();
    const environment = options.environment ?? process.env;
    const sentryDsn = environment.MD2_SENTRY_DSN;
    sentryEnabled = !options.isDevelopment && !!sentry && hasValue(sentryDsn);

    if (sentryEnabled) {
        try {
            sentry.init({ dsn: sentryDsn });
        } catch {
            sentryEnabled = false;
        }
    }

    const aptabase = options.aptabaseClient ?? loadAptabaseClient();
    const aptabaseAppKey = environment.MD2_APTABASE_APP_KEY;
    aptabaseEnabled = !!aptabase && hasValue(aptabaseAppKey);

    if (aptabaseEnabled) {
        aptabaseInitialize = aptabase.initialize;
        aptabaseTrackEvent = aptabase.trackEvent;

        try {
            await aptabaseInitialize(aptabaseAppKey);
        } catch {
            aptabaseEnabled = false;
        }
    }

    await trackEvent('electron_starting');
}

function registerProcessErrorHandlers() {
    process.on('uncaughtException', captureError);
    process.on('unhandledRejection', captureError);
}

function resetTelemetryForTests() {
    aptabaseEnabled = false;
    aptabaseInitialize = null;
    aptabaseTrackEvent = null;
    pendingAptabaseEvents = new Set();
    sentry = null;
    sentryEnabled = false;
}

module.exports = {
    captureError,
    flush,
    registerProcessErrorHandlers,
    resetTelemetryForTests,
    startElectronTelemetry,
    trackEvent,
};

