.\design\releases\0_2_0\card__1282901d-fbea-459b-92ab-6d82708948df.json:1558:          "content": "import { Box } from '@mui/material'\r\nimport { DndContext, DragOverlay, PointerSensor, closestCorners, useSensor, useSensors } from '@dnd-kit/core'\r\nimport type { DragEndEvent, DragOverEvent, DragStartEvent } from '@dnd-kit/core'\r\nimport { useCallback, useEffect, useRef, useState } from 'react'\r\nimport { buildCardColumns } from '../../data/card_ordering'\r\nimport type { CardTypeConfig, StateConfig } from '../../data/data_types'\r\nimport { dataService } from '../../services/data/data_service'\r\nimport { dialogService } from '../../services/dialog_service'\r\nimport { openFilesService } from '../../services/open_files_service'\r\nimport { workspaceViewService } from '../../services/project/workspace_view_service'\r\nimport { telemetryService } from '../../services/telemetry/telemetry_service'\r\nimport { AffectsEditorDialog } from './affects_editor_dialog'\r\nimport { CardBodyPopover } from './card_body_popover'\r\nimport { cardBodyPopoverService } from './card_body_popover_service'\r\nimport { CardColumn } from './card_column'\r\nimport { CardDragOverlay } from './card_drag_overlay'\r\nimport { cardDragDropService } from './card_drag_drop_service'\r\nimport { resolveCardDragEvent } from './card_drag'\r\nimport { useCardViewColumns } from './use_card_view_columns'\r\n\r\nconst DRAG_ACTIVATION_DISTANCE = 2\r\ninterface CardViewProps {\r\n    cardTypes: CardTypeConfig[]\r\n    states: StateConfig[]\r\n    statusColors: Map<string, string>\r\n}\r\n\r\nasync function runCardEdit(action: () => unknown, fallbackMessage: string) {\r\n    try {\r\n        await action()\r\n    } catch (error) {\r\n        dialogService.error(error, { fallbackMessage })\r\n    }\r\n}\r\n\r\nfunction currentCardColumns(states: StateConfig[]) {\r\n    const cards = dataService.getState().snapshot?.activeCards ?? []\r\n\r\n    return buildCardColumns(cards, states)\r\n}\r\n\r\n/** Card view: status columns of draggable cards with card-anchored body popup access. */\r\nexport function CardView(props: CardViewProps) {\r\n    const {\r\n        cardTypes,\r\n        states,\r\n        statusColors,\r\n    } = props\r\n    const columns = useCardViewColumns(states)\r\n    const [openAffectsPath, setOpenAffectsPath] = useState<string | null>(null)\r\n    const rootElementRef = useRef<HTMLDivElement>(null)\r\n    const dragColumnsRef = useRef<ReturnType<typeof currentCardColumns> | null>(null)\r\n    const lastOverIdRef = useRef<string | null>(null)\r\n    const missingRootReportedRef = useRef(false)\r\n    const wasVisibleRef = useRef<boolean | null>(null)\r\n    const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: DRAG_ACTIVATION_DISTANCE } }))\r\n\r\n    const handleOpenAffects = (path: string) => {\r\n        setOpenAffectsPath(path)\r\n    }\r\n\r\n    const handleCloseAffects = () => {\r\n        setOpenAffectsPath(null)\r\n    }\r\n\r\n    const clearActiveCard = useCallback(() => {\r\n        dragColumnsRef.current = null\r\n        lastOverIdRef.current = null\r\n        cardDragDropService.endDrag()\r\n    }, [])\r\n\r\n    useEffect(() => {\r\n        const updateVisibility = () => {\r\n            const rootElement = rootElementRef.current\r\n            if (!rootElement) {\r\n                if (!missingRootReportedRef.current) {\r\n                    missingRootReportedRef.current = true\r\n                    dialogService.error(new Error('Missing card view root element'), {fallbackMessage: 'Card view could not be displayed'})\r\n                }\r\n                return\r\n            }\r\n\r\n            const isVisible = workspaceViewService.getSnapshot().viewMode === 'cards'\r\n            rootElement.style.display = isVisible ? 'flex' : 'none'\r\n            if (wasVisibleRef.current === isVisible) return\r\n\r\n            wasVisibleRef.current = isVisible\r\n            if (isVisible) return\r\n\r\n            queueMicrotask(() => {\r\n                cardBodyPopoverService.close()\r\n                setOpenAffectsPath((currentPath) => currentPath === null ? currentPath : null)\r\n                clearActiveCard()\r\n            })\r\n        }\r\n\r\n        updateVisibility()\r\n        workspaceViewService.addEventListener('changed', updateVisibility)\r\n\r\n        return () => workspaceViewService.removeEventListener('changed', updateVisibility)\r\n    }, [clearActiveCard])\r\n\r\n    useEffect(() => () => cardBodyPopoverService.close(), [])\r\n\r\n    const handleDragStart = useCallback((event: DragStartEvent) => {\r\n        dragColumnsRef.current = currentCardColumns(states)\r\n        lastOverIdRef.current = null\r\n        cardDragDropService.startDrag(\r\n            String(event.active.id),\r\n            event.active.rect.current.initial?.height ?? null,\r\n            event.active.rect.current.initial?.width ?? null,\r\n        )\r\n    }, [states])\r\n\r\n    const handleDragOver = useCallback((event: DragOverEvent) => {\r\n        const { active, over } = event\r\n        const overId = over ? String(over.id) : null\r\n        if (lastOverIdRef.current === overId) return\r\n\r\n        lastOverIdRef.current = overId\r\n        if (!over) {\r\n            cardDragDropService.setDropPreview(null)\r\n            return\r\n        }\r\n\r\n        const dragColumns = dragColumnsRef.current\r\n        if (!dragColumns) throw new Error('Cannot update a card drop target before dragging starts')\r\n\r\n        const drop = resolveCardDragEvent(dragColumns, event)\r\n        const sourceColumn = dragColumns.find((column) => column.cards.some((card) => card.path === String(active.id)))\r\n        const dropPreview = drop && sourceColumn?.status !== drop.targetStatus ? drop : null\r\n        cardDragDropService.setDropPreview(dropPreview)\r\n    }, [])\r\n\r\n    const handleDragEnd = useCallback((event: DragEndEvent) => {\r\n        const { active, over } = event\r\n        const drop = over ? resolveCardDragEvent(currentCardColumns(states), event) : null\r\n        const path = String(active.id)\r\n        if (!drop) {\r\n            clearActiveCard()\r\n            return\r\n        }\r\n\r\n        clearActiveCard()\r\n        void runCardEdit(() => dataService.cards.moveCard(path, drop.targetStatus, drop.targetIndex), `Card move failed: ${path}`)\r\n    }, [clearActiveCard, states])\r\n\r\n    const handleOpenInFileMode = (path: string) => {\r\n        cardBodyPopoverService.close()\r\n        workspaceViewService.selectPath(path)\r\n        void runCardEdit(() => openFilesService.openPath(path), `File open failed: ${path}`)\r\n        workspaceViewService.setViewMode('text')\r\n        telemetryService.trackEvent('navigation')\r\n    }\r\n\r\n    const handleDeleteCard = async (path: string) => {\r\n        try {\r\n            await dataService.cards.deleteCard(path)\r\n            workspaceViewService.clearSelectedPath(path)\r\n            cardBodyPopoverService.closePath(path)\r\n            if (openAffectsPath === path) handleCloseAffects()\r\n        } catch (error) {\r\n            dialogService.error(error, { fallbackMessage: `Card delete failed: ${path}` })\r\n            throw error\r\n        }\r\n    }\r\n\r\n    const handleTitleChange = (path: string, title: string) => {\r\n        dataService.cards.updateCardTitle(path, title).catch((error: unknown) => {\r\n            dialogService.error(error, { fallbackMessage: `Title update failed: ${path}` })\r\n        })\r\n    }\r\n\r\n    const handleTogglePolicy = (path: string, policyKey: string) => {\r\n        void runCardEdit(() => dataService.cards.toggleCardPolicy(path, policyKey), `Policy toggle failed: ${path}`)\r\n    }\r\n\r\n    const handleAffectsChange = (path: string, affects: string[]) => {\r\n        void runCardEdit(() => dataService.cards.updateCardAffects(path, affects), `Affects update failed: ${path}`)\r\n    }\r\n\r\n    return (\r\n        <Box\r\n            ref={rootElementRef}\r\n            sx={{ bgcolor: 'background.default', display: 'flex', flex: 1, minHeight: 0, overflow: 'hidden', position: 'relative' }}\r\n        >\r\n            <DndContext\r\n                collisionDetection={closestCorners}\r\n                onDragCancel={clearActiveCard}\r\n                onDragEnd={handleDragEnd}\r\n                onDragOver={handleDragOver}\r\n                onDragStart={handleDragStart}\r\n                sensors={sensors}\r\n            >\r\n                <Box\r\n                    aria-label=\"Card columns\"\r\n                    sx={{\r\n                        alignItems: 'flex-start',\r\n                        display: 'flex',\r\n                        flex: 1,\r\n                        flexDirection: 'row',\r\n                        gap: 2,\r\n                        height: '100%',\r\n                        overflowX: 'auto',\r\n                        overflowY: 'auto',\r\n                        p: 2.5,\r\n                    }}\r\n                >\r\n                    {columns.map((column) => (\r\n                        <CardColumn\r\n                            key={column.status}\r\n                            cardTypes={cardTypes}\r\n                            column={column}\r\n                            isMobile={false}\r\n                            onDeleteCard={handleDeleteCard}\r\n                            onOpenInFileMode={handleOpenInFileMode}\r\n                            onTitleChange={handleTitleChange}\r\n                            onTogglePolicy={handleTogglePolicy}\r\n                        />\r\n                    ))}\r\n                </Box>\r\n                <DragOverlay>\r\n                    <CardDragOverlay cardTypes={cardTypes} />\r\n                </DragOverlay>\r\n                <CardBodyPopover\r\n                    cardTypes={cardTypes}\r\n                    isMobile={false}\r\n                    onDeleteCard={handleDeleteCard}\r\n                    onOpenAffects={handleOpenAffects}\r\n                    onOpenInFileMode={handleOpenInFileMode}\r\n                    statusColors={statusColors}\r\n                    visible\r\n                />\r\n                <AffectsEditorDialog\r\n                    cardPath={openAffectsPath}\r\n                    onClose={handleCloseAffects}\r\n                    onSave={handleAffectsChange}\r\n                />\r\n            </DndContext>\r\n        </Box>\r\n    )\r\n}\r\nimport { Box } from '@mui/material'\r\nimport { DndContext, DragOverlay, MouseSensor, TouchSensor, closestCorners, useSensor, useSensors } from '@dnd-kit/core'\r\nimport type { DragEndEvent, DragMoveEvent, DragStartEvent } from '@dnd-kit/core'\r\nimport { useCallback, useEffect, useRef, useState } from 'react'\r\nimport { buildCardColumns } from '../../data/card_ordering'\r\nimport type { CardTypeConfig, StateConfig } from '../../data/data_types'\r\nimport { dataService } from '../../services/data/data_service'\r\nimport { dialogService } from '../../services/dialog_service'\r\nimport { openFilesService } from '../../services/open_files_service'\r\nimport { workspaceViewService } from '../../services/project/workspace_view_service'\r\nimport { telemetryService } from '../../services/telemetry/telemetry_service'\r\nimport { CardActionPopupHost } from '../actions/run/popup/card_action_popup_host'\r\nimport { AffectsEditorDialog } from './affects_editor_dialog'\r\nimport { CardBodyPopover } from './card_body_popover'\r\nimport { cardBodyPopoverService } from './card_body_popover_service'\r\nimport { CardColumn } from './card_column'\r\nimport { CardDragOverlay } from './card_drag_overlay'\r\nimport { cardDragDropService } from './card_drag_drop_service'\r\nimport { useCardViewColumns } from './use_card_view_columns'\r\nimport { useMobileCardViewColumn } from './use_mobile_card_view_column'\r\nimport { resolveMobileCardDragEvent } from './mobile_card_drag'\r\n\r\nconst LONG_PRESS_DELAY_MS = 500\r\nconst LONG_PRESS_TOLERANCE = 5\r\n\r\ninterface MobileCardViewProps {\r\n    cardTypes: CardTypeConfig[]\r\n    states: StateConfig[]\r\n    statusColors: Map<string, string>\r\n}\r\n\r\nasync function runCardEdit(action: () => unknown, fallbackMessage: string) {\r\n    try {\r\n        await action()\r\n    } catch (error) {\r\n        dialogService.error(error, { fallbackMessage })\r\n    }\r\n}\r\n\r\nfunction currentCardColumns(states: StateConfig[]) {\r\n    const cards = dataService.getState().snapshot?.activeCards ?? []\r\n\r\n    return buildCardColumns(cards, states)\r\n}\r\n\r\n/** Mobile board showing one selected column with delayed touch dragging. */\r\nexport function MobileCardView(props: MobileCardViewProps) {\r\n    const { cardTypes, states, statusColors } = props\r\n    const columns = useCardViewColumns(states)\r\n    const selectedColumn = useMobileCardViewColumn(columns)\r\n    const [openAffectsPath, setOpenAffectsPath] = useState<string | null>(null)\r\n    const rootElementRef = useRef<HTMLDivElement>(null)\r\n    const wasVisibleRef = useRef<boolean | null>(null)\r\n    const sensors = useSensors(\r\n        useSensor(MouseSensor, { activationConstraint: { delay: LONG_PRESS_DELAY_MS, tolerance: LONG_PRESS_TOLERANCE } }),\r\n        useSensor(TouchSensor, { activationConstraint: { delay: LONG_PRESS_DELAY_MS, tolerance: LONG_PRESS_TOLERANCE } }),\r\n    )\r\n\r\n    const clearActiveCard = useCallback(() => {\r\n        cardDragDropService.endDrag()\r\n    }, [])\r\n\r\n    const handleCloseAffects = () => {\r\n        setOpenAffectsPath(null)\r\n    }\r\n\r\n    useEffect(() => {\r\n        const updateVisibility = () => {\r\n            const rootElement = rootElementRef.current\r\n            if (!rootElement) return\r\n\r\n            const isVisible = workspaceViewService.getSnapshot().viewMode === 'cards'\r\n            rootElement.style.display = isVisible ? 'flex' : 'none'\r\n            if (wasVisibleRef.current === isVisible) return\r\n\r\n            wasVisibleRef.current = isVisible\r\n            if (isVisible) return\r\n\r\n            queueMicrotask(() => {\r\n                cardBodyPopoverService.close()\r\n                setOpenAffectsPath((currentPath) => currentPath === null ? currentPath : null)\r\n                clearActiveCard()\r\n            })\r\n        }\r\n\r\n        updateVisibility()\r\n        workspaceViewService.addEventListener('changed', updateVisibility)\r\n\r\n        return () => workspaceViewService.removeEventListener('changed', updateVisibility)\r\n    }, [clearActiveCard])\r\n\r\n    useEffect(() => () => cardBodyPopoverService.close(), [])\r\n\r\n    const handleDragStart = useCallback((event: DragStartEvent) => {\r\n        cardDragDropService.startDrag(\r\n            String(event.active.id),\r\n            event.active.rect.current.initial?.height ?? null,\r\n            event.active.rect.current.initial?.width ?? null,\r\n        )\r\n    }, [])\r\n\r\n    const handleDragMove = useCallback((event: DragMoveEvent) => {\r\n        if (!selectedColumn) return\r\n\r\n        cardDragDropService.setDropPreview(resolveMobileCardDragEvent(currentCardColumns(states), selectedColumn.status, event))\r\n    }, [selectedColumn, states])\r\n\r\n    const handleDragEnd = useCallback((event: DragEndEvent) => {\r\n        const drop = selectedColumn ? resolveMobileCardDragEvent(currentCardColumns(states), selectedColumn.status, event) : null\r\n        clearActiveCard()\r\n        const path = String(event.active.id)\r\n        if (drop) void runCardEdit(() => dataService.cards.moveCard(path, drop.targetStatus, drop.targetIndex), `Card move failed: ${path}`)\r\n    }, [clearActiveCard, selectedColumn, states])\r\n\r\n    const handleOpenInFileMode = (path: string) => {\r\n        cardBodyPopoverService.close()\r\n        workspaceViewService.selectPath(path)\r\n        void runCardEdit(() => openFilesService.openPath(path), `File open failed: ${path}`)\r\n        workspaceViewService.setViewMode('text')\r\n        telemetryService.trackEvent('navigation')\r\n    }\r\n\r\n    const handleDeleteCard = async (path: string) => {\r\n        try {\r\n            await dataService.cards.deleteCard(path)\r\n            workspaceViewService.clearSelectedPath(path)\r\n            cardBodyPopoverService.closePath(path)\r\n            if (openAffectsPath === path) setOpenAffectsPath(null)\r\n        } catch (error) {\r\n            dialogService.error(error, { fallbackMessage: `Card delete failed: ${path}` })\r\n            throw error\r\n        }\r\n    }\r\n\r\n    const handleTitleChange = (path: string, title: string) => {\r\n        dataService.cards.updateCardTitle(path, title).catch((error: unknown) => {\r\n            dialogService.error(error, { fallbackMessage: `Title update failed: ${path}` })\r\n        })\r\n    }\r\n\r\n    const handleTogglePolicy = (path: string, policyKey: string) => {\r\n        void runCardEdit(() => dataService.cards.toggleCardPolicy(path, policyKey), `Policy toggle failed: ${path}`)\r\n    }\r\n\r\n    const handleAffectsChange = (path: string, affects: string[]) => {\r\n        void runCardEdit(() => dataService.cards.updateCardAffects(path, affects), `Affects update failed: ${path}`)\r\n    }\r\n\r\n    return (\r\n        <Box\r\n            aria-label=\"Mobile card board\"\r\n            ref={rootElementRef}\r\n            sx={{ bgcolor: 'background.default', display: 'flex', flex: 1, minHeight: 0, overflowX: 'hidden', overflowY: 'auto' }}\r\n        >\r\n            <DndContext\r\n                collisionDetection={closestCorners}\r\n                onDragCancel={clearActiveCard}\r\n                onDragEnd={handleDragEnd}\r\n                onDragMove={handleDragMove}\r\n                onDragStart={handleDragStart}\r\n                sensors={sensors}\r\n            >\r\n                <Box aria-label=\"Mobile card column\" sx={{ display: 'flex', flex: 1, minHeight: 0, width: '100%' }}>\r\n                    {selectedColumn ? (\r\n                        <CardColumn\r\n                            cardTypes={cardTypes}\r\n                            column={selectedColumn}\r\n                            isMobile\r\n                            onDeleteCard={handleDeleteCard}\r\n                            onOpenInFileMode={handleOpenInFileMode}\r\n                            onTitleChange={handleTitleChange}\r\n                            onTogglePolicy={handleTogglePolicy}\r\n                        />\r\n                    ) : null}\r\n                </Box>\r\n                <DragOverlay><CardDragOverlay cardTypes={cardTypes} /></DragOverlay>\r\n                <CardBodyPopover\r\n                    cardTypes={cardTypes}\r\n                    isMobile\r\n                    onDeleteCard={handleDeleteCard}\r\n                    onOpenAffects={setOpenAffectsPath}\r\n                    onOpenInFileMode={handleOpenInFileMode}\r\n                    statusColors={statusColors}\r\n                    visible\r\n                />\r\n                <AffectsEditorDialog cardPath={openAffectsPath} onClose={handleCloseAffects} onSave={handleAffectsChange} />\r\n                <CardActionPopupHost />\r\n            </DndContext>\r\n        </Box>\r\n    )\r\n}\r\nimport { Box, Paper, Typography, useMediaQuery, useTheme } from '@mui/material'\r\nimport { useCallback, useEffect, useMemo, useRef } from 'react'\r\nimport type { UseGithubAuthResult } from '../auth/use_github_auth'\r\nimport {\r\n    DEFAULT_CARD_TYPES,\r\n    DEFAULT_ACTIONS_FOLDER,\r\n    DEFAULT_ARCHIVED_FOLDER,\r\n    DEFAULT_PROJECT_FOLDER,\r\n    DEFAULT_RELEASES_FOLDER,\r\n    DEFAULT_STATES,\r\n    defaultColumnAccent,\r\n} from '../data/data_types'\r\nimport { dataService } from '../services/data/data_service'\r\nimport { dialogService } from '../services/dialog_service'\r\nimport { getElectronLifecycleBridge, type ElectronLifecycleBridge } from '../services/electron_lifecycle_bridge'\r\nimport { openFilesService } from '../services/open_files_service'\r\nimport type { OpenDocument } from '../services/open_files_service'\r\nimport { telemetryService } from '../services/telemetry/telemetry_service'\r\nimport { workspaceViewService } from '../services/project/workspace_view_service'\r\nimport { workspaceNavigationService, type WorkspaceOpenRequest } from '../services/project/workspace_navigation_service'\r\nimport { projectPersistenceService } from '../services/project/project_persistence_service'\r\nimport { CardView } from './card_view/card_view'\r\nimport { MobileCardViewMenu } from './card_view/mobile_card_view_menu'\r\nimport { MobileCardView } from './card_view/mobile_card_view'\r\nimport { CardActionPopupHost } from './actions/run/popup/card_action_popup_host'\r\nimport { flushMarkdownEditors } from './editor/markdown_editor_flush'\r\nimport { useProjectReference } from './hooks/use_project_reference'\r\nimport { TextView } from './text_view/text_view'\r\nimport { FileTreeView } from './text_view/file_tree_view'\r\nimport { useProjectConfig } from './hooks/use_project_config'\r\nimport { useWorkingFolder } from './hooks/use_working_folder'\r\nimport { ProjectWorkspaceAvailability } from './project_workspace_availability'\r\nimport { MobileLayout } from './shell/mobile_layout'\r\nimport { MobileMainWindow } from './shell/mobile_main_window'\r\nimport { SplitLayout } from './shell/split_layout'\r\n\r\nconst WORKSPACE_PANEL_PADDING = 3\r\n\r\nfunction openDocumentPath(document: OpenDocument) {\r\n    return document.kind === 'card' ? document.getObject().path : document.getObject().sourcePath\r\n}\r\n\r\nfunction flushPendingCommits() {\r\n    flushMarkdownEditors()\r\n    void projectPersistenceService.flushPendingChanges().catch((error: unknown) => {\r\n        dialogService.error(error, { fallbackMessage: 'Pending changes could not be saved' })\r\n    })\r\n}\r\n\r\nasync function flushAndConfirmPendingCommits(lifecycleBridge: ElectronLifecycleBridge, requestId: string) {\r\n    try {\r\n        flushMarkdownEditors()\r\n        await projectPersistenceService.flushPendingChanges()\r\n        lifecycleBridge.confirmFlush(requestId)\r\n    } catch (error) {\r\n        dialogService.error(error, { fallbackMessage: 'Pending changes could not be saved before closing' })\r\n    }\r\n}\r\n\r\nfunction runWorkspaceEdit(action: () => void, fallbackMessage: string) {\r\n    try {\r\n        action()\r\n    } catch (error) {\r\n        dialogService.error(error, { fallbackMessage })\r\n    }\r\n}\r\n\r\ninterface ProjectWorkspaceProps {\r\n    auth: UseGithubAuthResult\r\n    isMenuOpen: boolean\r\n    onLeftPanelInteraction: () => void\r\n}\r\n\r\nexport function ProjectWorkspace(props: ProjectWorkspaceProps) {\r\n    const { auth, isMenuOpen, onLeftPanelInteraction } = props\r\n    const theme = useTheme()\r\n    const isMobile = useMediaQuery(theme.breakpoints.down('md'))\r\n    const project = useProjectReference()\r\n    const projectConfig = useProjectConfig()\r\n    const workingFolder = useWorkingFolder()\r\n    const cardTypes = projectConfig?.cardTypes ?? DEFAULT_CARD_TYPES\r\n    const states = projectConfig?.states ?? DEFAULT_STATES\r\n    const projectFolder = projectConfig?.projectFolder ?? DEFAULT_PROJECT_FOLDER\r\n    const actionsFolder = projectConfig?.actionsFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ACTIONS_FOLDER}`\r\n    const archivedFolder = projectConfig?.archivedFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ARCHIVED_FOLDER}`\r\n    const releasesFolder = projectConfig?.releasesFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_RELEASES_FOLDER}`\r\n    const mobileScrollContainerRef = useRef<HTMLDivElement>(null)\r\n    const onLeftPanelInteractionRef = useRef(onLeftPanelInteraction)\r\n    const statusColors = useMemo(() => new Map(\r\n        states.map(({ color, state }, index) => [state, color ?? defaultColumnAccent(index)]),\r\n    ), [states])\r\n\r\n    useEffect(() => {\r\n        onLeftPanelInteractionRef.current = onLeftPanelInteraction\r\n    })\r\n\r\n    const handleCreateFolder = useCallback(async (parentDirectory: string, name: string) => {\r\n        await dataService.cards.createFolder(parentDirectory, name)\r\n    }, [])\r\n\r\n    const handleCreateMarkdownFile = useCallback(async (parentDirectory: string, name: string) => {\r\n        await dataService.cards.createMarkdownFile(parentDirectory, name)\r\n    }, [])\r\n\r\n    const handleDeleteFile = useCallback(async (path: string) => {\r\n        try {\r\n            await dataService.cards.deleteFile(path)\r\n            const document = openFilesService.getSnapshot().documents.find((candidate) => openDocumentPath(candidate) === path)\r\n            if (document) openFilesService.closeDocument(document)\r\n            workspaceViewService.clearSelectedPath(path)\r\n            onLeftPanelInteractionRef.current()\r\n        } catch (error) {\r\n            dialogService.error(error, { fallbackMessage: `File delete failed: ${path}` })\r\n            throw error\r\n        }\r\n    }, [])\r\n\r\n    const handleDeleteFolder = useCallback(async (path: string) => {\r\n        try {\r\n            await dataService.cards.deleteFolder(path)\r\n            const folderPrefix = `${path.replace(/\\/+$/u, '')}/`\r\n            const documents = openFilesService.getSnapshot().documents\r\n            for (const document of documents) {\r\n                const openPath = openDocumentPath(document)\r\n                if (openPath?.startsWith(folderPrefix)) openFilesService.closeDocument(document)\r\n            }\r\n            const selectedPath = workspaceViewService.getSnapshot().selectedPath\r\n            if (selectedPath?.startsWith(folderPrefix)) workspaceViewService.clearSelectedPath(selectedPath)\r\n            onLeftPanelInteractionRef.current()\r\n        } catch (error) {\r\n            dialogService.error(error, { fallbackMessage: `Folder deletion failed: ${path}` })\r\n            throw error\r\n        }\r\n    }, [])\r\n\r\n    useEffect(() => {\r\n        const handleBeforeUnload = (event: BeforeUnloadEvent) => {\r\n            flushMarkdownEditors()\r\n            const { hasPendingPush, hasPendingSave } = projectPersistenceService.getSnapshot()\r\n            // In Electron, vetoing beforeunload silently cancels the window close (no confirm\r\n            // dialog), leaving the app unclosable. The main process flushes pending commits on\r\n            // quit instead, so only prompt in a plain browser build.\r\n            if ((hasPendingPush || hasPendingSave) && !getElectronLifecycleBridge()) {\r\n                event.preventDefault()\r\n                event.returnValue = ''\r\n            }\r\n\r\n            flushPendingCommits()\r\n        }\r\n\r\n        const handleVisibilityChange = () => {\r\n            if (document.visibilityState === 'hidden') flushPendingCommits()\r\n        }\r\n\r\n        const handleBlur = () => {\r\n            flushMarkdownEditors()\r\n            if (projectPersistenceService.getSnapshot().hasPendingSave) flushPendingCommits()\r\n        }\r\n\r\n        document.addEventListener('visibilitychange', handleVisibilityChange)\r\n        window.addEventListener('beforeunload', handleBeforeUnload)\r\n        window.addEventListener('blur', handleBlur)\r\n\r\n        return () => {\r\n            document.removeEventListener('visibilitychange', handleVisibilityChange)\r\n            window.removeEventListener('beforeunload', handleBeforeUnload)\r\n            window.removeEventListener('blur', handleBlur)\r\n        }\r\n    }, [])\r\n\r\n    useEffect(() => {\r\n        const lifecycleBridge = getElectronLifecycleBridge()\r\n        if (!lifecycleBridge) return undefined\r\n\r\n        return lifecycleBridge.onFlushRequested((requestId) => {\r\n            void flushAndConfirmPendingCommits(lifecycleBridge, requestId)\r\n        })\r\n    }, [])\r\n\r\n    useEffect(() => {\r\n        const handleNavigationOpen = (event: Event) => {\r\n            const { path } = (event as CustomEvent<WorkspaceOpenRequest>).detail\r\n            // Reveal the card/file without changing the current view mode: highlight it in card view\r\n            // and open it in the service-owned text-view tabs.\r\n            workspaceViewService.selectPath(path)\r\n            runWorkspaceEdit(() => openFilesService.openPath(path), `File open failed: ${path}`)\r\n            telemetryService.trackEvent('navigation')\r\n        }\r\n\r\n        workspaceNavigationService.addEventListener('open', handleNavigationOpen)\r\n\r\n        return () => workspaceNavigationService.removeEventListener('open', handleNavigationOpen)\r\n    }, [])\r\n\r\n    const fileTree = (\r\n        <Box\r\n            aria-label=\"File tree\"\r\n            sx={{ bgcolor: 'action.hover', display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0 }}\r\n        >\r\n            <FileTreeView\r\n                actionsFolder={actionsFolder}\r\n                archivedFolder={archivedFolder}\r\n                cardTypes={cardTypes}\r\n                onCreateFolder={handleCreateFolder}\r\n                onCreateMarkdownFile={handleCreateMarkdownFile}\r\n                onDeleteFile={handleDeleteFile}\r\n                onDeleteFolder={handleDeleteFolder}\r\n                onLeftPanelInteraction={onLeftPanelInteraction}\r\n                projectFolder={projectFolder}\r\n                releasesFolder={releasesFolder}\r\n                statusColors={statusColors}\r\n                workingFolder={workingFolder}\r\n            />\r\n        </Box>\r\n    )\r\n    const textView = (\r\n        <Paper\r\n            elevation={0}\r\n            sx={{\r\n                border: 1,\r\n                borderColor: 'divider',\r\n                borderRadius: 2,\r\n                boxSizing: 'border-box',\r\n                display: 'flex',\r\n                height: '100%',\r\n                minHeight: 0,\r\n                overflow: 'hidden',\r\n                p: WORKSPACE_PANEL_PADDING,\r\n            }}\r\n        >\r\n            <TextView\r\n                actionsFolder={actionsFolder}\r\n                archivedFolder={archivedFolder}\r\n                cardTypes={cardTypes}\r\n                projectFolder={projectFolder}\r\n                releasesFolder={releasesFolder}\r\n                states={states}\r\n            />\r\n        </Paper>\r\n    )\r\n\r\n    const workspace = (\r\n        <ProjectWorkspaceAvailability>\r\n            {isMobile ? <MobileLayout content={textView} /> : <SplitLayout left={fileTree} right={textView} />}\r\n            {isMobile ? (\r\n                <MobileCardView cardTypes={cardTypes} states={states} statusColors={statusColors} />\r\n            ) : (\r\n                <CardView cardTypes={cardTypes} states={states} statusColors={statusColors} />\r\n            )}\r\n            <CardActionPopupHost />\r\n        </ProjectWorkspaceAvailability>\r\n    )\r\n    const navigation = project ? fileTree : (\r\n        <Box sx={{ p: 2 }}>\r\n            <Typography color=\"text.secondary\" variant=\"body2\">\r\n                No project navigation available.\r\n            </Typography>\r\n        </Box>\r\n    )\r\n\r\n    return (\r\n        <Box\r\n            aria-label=\"Project workspace\"\r\n            component=\"section\"\r\n            sx={{ display: 'flex', flex: 1, minHeight: 0, overflow: isMobile ? 'unset' : 'hidden' }}\r\n        >\r\n            {isMobile ? (\r\n                <MobileMainWindow\r\n                    auth={auth}\r\n                    cardNavigation={project ? <MobileCardViewMenu onSelected={onLeftPanelInteraction} states={states} /> : null}\r\n                    isMenuOpen={isMenuOpen}\r\n                    leftPanel={navigation}\r\n                    onCloseMenu={onLeftPanelInteraction}\r\n                    rightPanel={workspace}\r\n                    rightPanelContainerRef={mobileScrollContainerRef}\r\n                    showNavigationInCards={!project}\r\n                />\r\n            ) : workspace}\r\n        </Box>\r\n    )\r\n}\r\n",
