mns.find((column) => column.cards.some((card) => card.path === String(active.id)))\n        const dropPreview = drop && sourceColumn?.status !== drop.targetStatus ? drop : null\n        cardDragDropService.setDropPreview(dropPreview)\n    }, [states])\n\n    const handleDragEnd = useCallback((event: DragEndEvent) => {\n        const { active, over } = event\n        const drop = over ? resolveCardDragEvent(currentCardColumns(states), event) : null\n        clearActiveCard()\n        const path = String(active.id)\n        if (drop) void runCardEdit(() => dataService.cards.moveCard(path, drop.targetStatus, drop.targetIndex), `Card move failed: ${path}`)\n    }, [clearActiveCard, states])\n\n    const handleOpenInFileMode = (path: string) => {\n        cardBodyPopoverService.close()\n        workspaceViewService.selectPath(path)\n        void runCardEdit(() => openFilesService.openPath(path), `File open failed: ${path}`)\n        workspaceViewService.setViewMode('text')\n        telemetryService.trackEvent('navigation')\n    }\n\n    const handleDeleteCard = async (path: string) => {\n        try {\n            await dataService.cards.deleteCard(path)\n            workspaceViewService.clearSelectedPath(path)\n            cardBodyPopoverService.closePath(path)\n            if (openAffectsPath === path) handleCloseAffects()\n        } catch (error) {\n            dialogService.error(error, { fallbackMessage: `Card delete failed: ${path}` })\n            throw error\n        }\n    }\n\n    const handleTitleChange = (path: string, title: string) => {\n        dataService.cards.updateCardTitle(path, title).catch((error: unknown) => {\n            dialogService.error(error, { fallbackMessage: `Title update failed: ${path}` })\n        })\n    }\n\n    const handleTogglePolicy = (path: string, policyKey: string) => {\n        void runCardEdit(() => dataService.cards.toggleCardPolicy(path, policyKey), `Policy toggle failed: ${path}`)\n    }\n\n    const handleAffectsChange = (path: string, affects: string[]) => {\n        void runCardEdit(() => dataService.cards.updateCardAffects(path, affects), `Affects update failed: ${path}`)\n    }\n\n    return (\n        <Box\n            ref={rootElementRef}\n            sx={{ bgcolor: 'background.default', display: 'flex', flex: 1, minHeight: 0, overflow: 'hidden', position: 'relative' }}\n        >\n            <DndContext\n                collisionDetection={closestCorners}\n                onDragCancel={clearActiveCard}\n                onDragEnd={handleDragEnd}\n                onDragMove={handleDragMove}\n                onDragStart={handleDragStart}\n                sensors={sensors}\n            >\n                <Box\n                    aria-label=\"Card columns\"\n                    ref={scrollContainerRef}\n                    sx={{\n                        alignItems: 'flex-start',\n                        display: 'flex',\n                        flex: 1,\n                        flexDirection: isMobile ? 'column' : 'row',\n                        gap: 2,\n                        height: '100%',\n                        overflowX: isMobile ? 'hidden' : 'auto',\n                        overflowY: 'auto',\n                        p: 2.5,\n                    }}\n                >\n                    {columns.map((column) => (\n                        <CardColumn\n                            key={column.status}\n                            cardTypes={cardTypes}\n                            column={column}\n                            isMobile={isMobile}\n                            onDeleteCard={handleDeleteCard}\n                            onOpenInFileMode={handleOpenInFileMode}\n                            onTitleChange={handleTitleChange}\n                            onTogglePolicy={handleTogglePolicy}\n                        />\n                    ))}\n                </Box>\n                {isMobile && <CardViewScrollZones scrollContainerRef={scrollContainerRef} />}\n                <DragOverlay>\n                    <CardDragOverlay cardTypes={cardTypes} />\n                </DragOverlay>\n                <CardBodyPopover\n                    isMobile={isMobile}\n                    onDeleteCard={handleDeleteCard}\n                    onOpenAffects={handleOpenAffects}\n                    onOpenInFileMode={handleOpenInFileMode}\n                    visible\n                />\n                <AffectsEditorDialog\n                    cardPath={openAffectsPath}\n                    onClose={handleCloseAffects}\n                    onSave={handleAffectsChange}\n                />\n                <CardActionPopupHost />\n            </DndContext>\n        </Box>\n    )\n}\n\r\nimport { Box } from '@mui/material'\nimport { useSortable } from '@dnd-kit/sortable'\nimport { useCallback } from 'react'\nimport type { MouseEventHandler, ReactNode, TouchEventHandler } from 'react'\n\nexport interface ProjectCardDragInteractions {\n    onClick: MouseEventHandler<HTMLElement>\n    onContextMenu: MouseEventHandler<HTMLElement>\n    onTouchEnd: TouchEventHandler<HTMLElement>\n    onTouchStart: TouchEventHandler<HTMLElement>\n}\n\ninterface ProjectCardDragContainerProps {\n    cardId: string\n    cardPath: string\n    children: ReactNode\n    interactions: ProjectCardDragInteractions\n    isBodyOpen: boolean\n    isSelected: boolean\n    onCardElementChange: (element: HTMLDivElement | null) => void\n}\n\n/** Lightweight sortable adapter that updates only card drag DOM around stable card content. */\nexport function ProjectCardDragContainer(props: ProjectCardDragContainerProps) {\n    const {cardId, cardPath, children, interactions, isBodyOpen, isSelected, onCardElementChange} = props\n    const { onClick, onContextMenu, onTouchEnd, onTouchStart } = interactions\n    const sortable = useSortable({ id: cardPath })\n    const { attributes, isDragging, listeners, setActivatorNodeRef, setNodeRef, transform, transition } = sortable\n    const dragTranslation = transform ? `translate3d(${transform.x}px, ${transform.y}px, 0)` : ''\n    const transformStyle = `${dragTranslation}${isDragging ? ' rotate(2deg)' : ''}`.trim() || undefined\n    const setCardElement = useCallback((element: HTMLDivElement | null) => {\n        setNodeRef(element)\n        onCardElementChange(element)\n    }, [onCardElementChange, setNodeRef])\n\n    return (\n        <Box\n            data-card-path={cardPath}\n            data-selected={isSelected ? 'true' : undefined}\n            onContextMenu={onContextMenu}\n            onTouchCancel={onTouchEnd}\n            onTouchEnd={onTouchEnd}\n            onTouchMove={onTouchEnd}\n            onTouchStart={onTouchStart}\n            ref={setCardElement}\n            sx={{\n                bgcolor: 'background.paper',\n                border: 1,\n                borderColor: isSelected ? 'primary.main' : 'divider',\n                borderRadius: 1.25,\n                boxShadow: isDragging ? 'var(--md2-card-drag-shadow)' : 'var(--md2-card-shadow)',\n                opacity: isDragging ? 0 : 1,\n                overflow: 'hidden',\n                position: 'relative',\n                transform: transformStyle,\n                transition,\n                '&:hover': { borderColor: 'text.disabled', boxShadow: 'var(--md2-card-hover-shadow)' },\n            }}\n        >\n            <Box\n                {...attributes}\n                {...listeners}\n                aria-expanded={isBodyOpen}\n                aria-haspopup=\"dialog\"\n                aria-label={`Drag ${cardId}`}\n                component=\"button\"\n                onClick={onClick}\n                ref={setActivatorNodeRef}\n                sx={{\n                    bgcolor: 'transparent',\n                    border: 0,\n                    cursor: isDragging ? 'grabbing' : 'pointer',\n                    inset: 0,\n                    position: 'absolute',\n                    touchAction: 'none',\n                    zIndex: 1,\n                    '&:focus-visible': { outline: '2px solid', outlineColor: 'primary.main', outlineOffset: -2 },\n                }}\n                type=\"button\"\n            />\n            {children}\n        </Box>\n    )\n}\n\r\nimport { Box, Paper, Typography, useMediaQuery, useTheme } from '@mui/material'\nimport { useCallback, useEffect, useMemo, useRef } from 'react'\nimport type { UseGithubAuthResult } from '../auth/use_github_auth'\nimport {\n    DEFAULT_CARD_TYPES,\n    DEFAULT_ACTIONS_FOLDER,\n    DEFAULT_ARCHIVED_FOLDER,\n    DEFAULT_PROJECT_FOLDER,\n    DEFAULT_RELEASES_FOLDER,\n    DEFAULT_STATES,\n    defaultColumnAccent,\n} from '../data/data_types'\nimport { dataService } from '../services/data/data_service'\nimport { dialogService } from '../services/dialog_service'\nimport { getElectronLifecycleBridge, type ElectronLifecycleBridge } from '../services/electron_lifecycle_bridge'\nimport { openFilesService } from '../services/open_files_service'\nimport type { OpenDocument } from '../services/open_files_service'\nimport { telemetryService } from '../services/telemetry/telemetry_service'\nimport { workspaceViewService } from '../services/project/workspace_view_service'\nimport { workspaceNavigationService, type WorkspaceOpenRequest } from '../services/project/workspace_navigation_service'\nimport { projectPersistenceService } from '../services/project/project_persistence_service'\nimport { CardView } from './card_view/card_view'\nimport { flushMarkdownEditors } from './editor/markdown_editor_flush'\nimport { useProjectReference } from './hooks/use_project_reference'\nimport { TextView } from './text_view/text_view'\nimport { FileTreeView } from './text_view/file_tree_view'\nimport { useProjectConfig } from './hooks/use_project_config'\nimport { useWorkingFolder } from './hooks/use_working_folder'\nimport { ProjectWorkspaceAvailability } from './project_workspace_availability'\nimport { MobileLayout } from './shell/mobile_layout'\nimport { MobileMainWindow } from './shell/mobile_main_window'\nimport { SplitLayout } from './shell/split_layout'\n\nconst WORKSPACE_PANEL_PADDING = 3\n\nfunction openDocumentPath(document: OpenDocument) {\n    return document.kind === 'card' ? document.getObject().path : document.getObject().sourcePath\n}\n\nfunction flushPendingCommits() {\n    flushMarkdownEditors()\n    void projectPersistenceService.flushPendingChanges().catch((error: unknown) => {\n        dialogService.error(error, { fallbackMessage: 'Pending changes could not be saved' })\n    })\n}\n\nasync function flushAndConfirmPendingCommits(lifecycleBridge: ElectronLifecycleBridge, requestId: string) {\n    try {\n        flushMarkdownEditors()\n        await projectPersistenceService.flushPendingChanges()\n        lifecycleBridge.confirmFlush(requestId)\n    } catch (error) {\n        dialogService.error(error, { fallbackMessage: 'Pending changes could not be saved before closing' })\n    }\n}\n\nfunction runWorkspaceEdit(action: () => void, fallbackMessage: string) {\n    try {\n        action()\n    } catch (error) {\n        dialogService.error(error, { fallbackMessage })\n    }\n}\n\ninterface ProjectWorkspaceProps {\n    auth: UseGithubAuthResult\n    isMenuOpen: boolean\n    onLeftPanelInteraction: () => void\n}\n\nexport function ProjectWorkspace(props: ProjectWorkspaceProps) {\n    const { auth, isMenuOpen, onLeftPanelInteraction } = props\n    const theme = useTheme()\n    const isMobile = useMediaQuery(theme.breakpoints.down('md'))\n    const project = useProjectReference()\n    const projectConfig = useProjectConfig()\n    const workingFolder = useWorkingFolder()\n    const cardTypes = projectConfig?.cardTypes ?? DEFAULT_CARD_TYPES\n    const states = projectConfig?.states ?? DEFAULT_STATES\n    const projectFolder = projectConfig?.projectFolder ?? DEFAULT_PROJECT_FOLDER\n    const actionsFolder = projectConfig?.actionsFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ACTIONS_FOLDER}`\n    const archivedFolder = projectConfig?.archivedFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ARCHIVED_FOLDER}`\n    const releasesFolder = projectConfig?.releasesFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_RELEASES_FOLDER}`\n    const onLeftPanelInteractionRef = useRef(onLeftPanelInteraction)\n    const statusColors = useMemo(() => new Map(\n        states.map(({ color, state }, index) => [state, color ?? defaultColumnAccent(index)]),\n    ), [states])\n\n    useEffect(() => {\n        onLeftPanelInteractionRef.current = onLeftPanelInteraction\n    })\n\n    const handleCreateFolder = useCallback(async (parentDirectory: string, name: string) => {\n        await dataService.cards.createFolder(parentDirectory, name)\n    }, [])\n\n    const handleCreateMarkdownFile = useCallback(async (parentDirectory: string, name: string) => {\n        await dataService.cards.createMarkdownFile(parentDirectory, name)\n    }, [])\n\n    const handleDeleteFile = useCallback(async (path: string) => {\n        try {\n            await dataService.cards.deleteFile(path)\n            const document = openFilesService.getSnapshot().documents.find((candidate) => openDocumentPath(candidate) === path)\n            if (document) openFilesService.closeDocument(document)\n            workspaceViewService.clearSelectedPath(path)\n            onLeftPanelInteractionRef.current()\n        } catch (error) {\n            dialogService.error(error, { fallbackMessage: `File delete failed: ${path}` })\n            throw error\n        }\n    }, [])\n\n    const handleDeleteFolder = useCallback(async (path: string) => {\n        try {\n            await dataService.cards.deleteFolder(path)\n            const folderPrefix = `${path.replace(/\\/+$/u, '')}/`\n            const documents = openFilesService.getSnapshot().documents\n            for (const document of documents) {\n                const openPath = openDocumentPath(document)\n                if (openPath?.startsWith(folderPrefix)) openFilesService.closeDocument(document)\n            }\n            const selectedPath = workspaceViewService.getSnapshot().selectedPath\n            if (selectedPath?.startsWith(folderPrefix)) workspaceViewService.clearSelectedPath(selectedPath)\n            onLeftPanelInteractionRef.current()\n        } catch (error) {\n            dialogService.error(error, { fallbackMessage: `Folder deletion failed: ${path}` })\n            throw error\n        }\n    }, [])\n\n    useEffect(() => {\n        const handleBeforeUnload = (event: BeforeUnloadEvent) => {\n            flushMarkdownEditors()\n            const { hasPendingPush, hasPendingSave } = projectPersistenceService.getSnapshot()\n            // In Electron, vetoing beforeunload silently cancels the window close (no confirm\n            // dialog), leaving the app unclosable. The main process flushes pending commits on\n            // quit instead, so only prompt in a plain browser build.\n            if ((hasPendingPush || hasPendingSave) && !getElectronLifecycleBridge()) {\n                event.preventDefault()\n                event.returnValue = ''\n            }\n\n            flushPendingCommits()\n        }\n\n        const handleVisibilityChange = () => {\n            if (document.visibilityState === 'hidden') flushPendingCommits()\n        }\n\n        const handleBlur = () => {\n            flushMarkdownEditors()\n            if (projectPersistenceService.getSnapshot().hasPendingSave) flushPendingCommits()\n        }\n\n        document.addEventListener('visibilitychange', handleVisibilityChange)\n        window.addEventListener('beforeunload', handleBeforeUnload)\n        window.addEventListener('blur', handleBlur)\n\n        return () => {\n            document.removeEventListener('visibilitychange', handleVisibilityChange)\n            window.removeEventListener('beforeunload', handleBeforeUnload)\n            window.removeEventListener('blur', handleBlur)\n        }\n    }, [])\n\n    useEffect(() => {\n        const lifecycleBridge = getElectronLifecycleBridge()\n        if (!lifecycleBridge) return undefined\n\n        return lifecycleBridge.onFlushRequested((requestId) => {\n            void flushAndConfirmPendingCommits(lifecycleBridge, requestId)\n        })\n    }, [])\n\n    useEffect(() => {\n        const handleNavigationOpen = (event: Event) => {\n            const { path } = (event as CustomEvent<WorkspaceOpenRequest>).detail\n            // Reveal the card/file without changing the current view mode: highlight it in card view\n            // and open it in the service-owned text-view tabs.\n            workspaceViewService.selectPath(path)\n            runWorkspaceEdit(() => openFilesService.openPath(path), `File open failed: ${path}`)\n            telemetryService.trackEvent('navigation')\n        }\n\n        workspaceNavigationService.addEventListener('open', handleNavigationOpen)\n\n        return () => workspaceNavigationService.removeEventListener('open', handleNavigationOpen)\n    }, [])\n\n    const fileTree = (\n        <Box\n            aria-label=\"File tree\"\n            sx={{ bgcolor: 'action.hover', display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0 }}\n        >\n            <FileTreeView\n                actionsFolder={actionsFolder}\n                archivedFolder={archivedFolder}\n                cardTypes={cardTypes}\n                onCreateFolder={handleCreateFolder}\n                onCreateMarkdownFile={handleCreateMarkdownFile}\n                onDeleteFile={handleDeleteFile}\n                onDeleteFolder={handleDeleteFolder}\n                onLeftPanelInteraction={onLeftPanelInteraction}\n                projectFolder={projectFolder}\n                releasesFolder={releasesFolder}\n                statusColors={statusColors}\n                workingFolder={workingFolder}\n            />\n        </Box>\n    )\n    const textView = (\n        <Paper\n            elevation={0}\n            sx={{\n                border: 1,\n                borderColor: 'divider',\n                borderRadius: 2,\n                boxSizing: 'border-box',\n                display: 'flex',\n                height: '100%',\n                minHeight: 0,\n                overflow: 'hidden',\n                p: WORKSPACE_PANEL_PADDING,\n            }}\n        >\n            <TextView\n                actionsFolder={actionsFolder}\n                archivedFolder={archivedFolder}\n                cardTypes={cardTypes}\n                projectFolder={projectFolder}\n                releasesFolder={releasesFolder}\n                states={states}\n            />\n        </Paper>\n    )\n    const views = (\n        <>\n            {isMobile ? <MobileLayout content={textView} /> : <SplitLayout left={fileTree} right={textView} />}\n            <CardView cardTypes={cardTypes} isMobile={isMobile} states={states} />\n        </>\n    )\n    const workspace = (\n        <ProjectWorkspaceAvailability>\n            {views}\n        </ProjectWorkspaceAvailability>\n    )\n    const navigation = project ? fileTree : (\n        <Box sx={{ p: 2 }}>\n            <Typography color=\"text.secondary\" variant=\"body2\">\n                No project navigation available.\n            </Typography>\n        </Box>\n    )\n\n    return (\n        <Box\n            aria-label=\"Project workspace\"\n            component=\"section\"\n            sx={{ display: 'flex', flex: 1, minHeight: 0, overflow: 'hidden' }}\n        >\n            {isMobile ? (\n                <MobileMainWindow\n                    auth={auth}\n                    isMenuOpen={isMenuOpen}\n                    leftPanel={navigation}\n                    onCloseMenu={onLeftPanelInteraction}\n                    rightPanel={workspace}\n                    showNavigationInCards={!project}\n                />\n            ) : workspace}\n        </Box>\n    )\n}\n\r\nimport { act, cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react'\nimport { DndContext } from '@dnd-kit/core'\nimport { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'\nimport { CardView } from './card_view'\nimport { CardColumn } from './card_column'\nimport * as cardColumnModule from './card_column'\nimport { actionService } from '../../services/actions/action_service'\nimport type { ActionFile } from '../../data/action_types'\nimport { DEFAULT_CARD_TYPES, type CardTypeConfig, type ProjectCard } from '../../data/data_types'\nimport { telemetryService } from '../../services/telemetry/telemetry_service'\nimport { AppThemeProvider } from '../../theme/theme_provider'\nimport { dataService } from '../../services/data/data_service'\nimport { worktreeService } from '../../services/project/worktree_service'\nimport { cardMarkdownDataSource } from '../editor/card_markdown_data_source'\nimport { openFilesService } from '../../services/open_files_service'\nimport { workspaceViewService } from '../../services/project/workspace_view_service'\nimport { cardDragDropService } from './card_drag_drop_service'\n\nfunction card(id: string, title: string, status: string, policy: Record<string, boolean> = {}): ProjectCard {\n    return {\n        agentConversationErrors: [],\n        agentConversations: [],\n        headerFields: {},\n        content: `# ${title}\\n\\nBody of ${id}`,\n        header: {\n            affects: [], after: null, agentLogReferences: [], author: null, id, internalId: id.toLowerCase(), owner: null,\n            policy, status, title,\n            worktree: null, worktreeError: null, worktreeValue: null,\n        },\n        isActive: true,\n        path: `design/${id}.md`,\n    }\n}\n\nconst cards = [\n    card('F-1', 'First', 'todo', { checkLinting: true, requireTests: false }),\n    card('F-2', 'Second', 'done'),\n]\n\nfunction setProjectCards(activeCards: ProjectCard[], repositoryFiles = ['app/src/app.tsx', 'design/F-1.md']) {\n    vi.mocked(dataService.getState).mockReturnValue({\n        project: { branch: 'main', id: 'project', rootPath: 'C:\\\\project' },\n        runningAgents: [],\n        snapshot: { activeCards, backgroundCards: [], repositoryFiles, workingFolder: 'design' },\n    })\n}\n\nfunction actionFile(definition: unknown): ActionFile {\n    return { content: JSON.stringify(definition), path: 'actions/action.json' }\n}\n\nfunction createColumnHandlers() {\n    return {\n        onDeleteCard: vi.fn(async () => undefined),\n        onOpenInFileMode: vi.fn(),\n        onTitleChange: vi.fn(),\n        onTogglePolicy: vi.fn(),\n    }\n}\n\nfunction renderCardView(\n    overrides: Partial<Parameters<typeof CardView>[0]> = {},\n    activeCards = cards,\n    repositoryFiles = ['app/src/app.tsx', 'design/F-1.md'],\n) {\n    setProjectCards(activeCards, repositoryFiles)\n\n    render(\n        <AppThemeProvider>\n            <CardView\n                cardTypes={DEFAULT_CARD_TYPES}\n                isMobile={false}\n                states={[\n                    { alwaysVisible: false, state: 'todo' },\n                    { alwaysVisible: false, state: 'done' },\n                ]}\n                {...overrides}\n            />\n        </AppThemeProvider>,\n    )\n}\n\ndescribe('CardView', () => {\n    beforeEach(() => {\n        workspaceViewService.setViewMode('cards')\n        cardDragDropService.endDrag()\n        vi.spyOn(dataService, 'getState')\n        setProjectCards(cards)\n        vi.spyOn(dataService.cards, 'deleteCard').mockResolvedValue(null)\n        vi.spyOn(dataService.cards, 'moveCard').mockResolvedValue([])\n        vi.spyOn(dataService.cards, 'toggleCardPolicy').mockReturnValue(cards[0])\n        vi.spyOn(dataService.cards, 'updateCardAffects').mockReturnValue(cards[0])\n        vi.spyOn(dataService.cards, 'updateCardTitle').mockResolvedValue(cards[0])\n        vi.spyOn(openFilesService, 'openPath')\n        vi.spyOn(dataService, 'hasPendingFile').mockReturnValue(false)\n        vi.spyOn(cardMarkdownDataSource, 'getMarkdown').mockImplementation((target) => target.document.kind === 'card'\n            ? target.document.getDraft().content\n            : '')\n        vi.spyOn(cardMarkdownDataSource, 'commit').mockReturnValue(true)\n        vi.spyOn(cardMarkdownDataSource, 'updateActiveCardTitle').mockImplementation(() => undefined)\n    })\n\n    afterEach(() => {\n        cleanup()\n        cardDragDropService.endDrag()\n        const { selectedPath } = workspaceViewService.getSnapshot()\n        if (selectedPath) workspaceViewService.clearSelectedPath(selectedPath)\n        for (const document of openFilesService.getRegisteredDocuments()) openFilesService.discardDocument(document)\n        actionService.clear()\n        vi.restoreAllMocks()\n    })\n\n    it('keeps hidden card columns mounted without occupying layout', () => {\n        workspaceViewService.setViewMode('text')\n        renderCardView()\n\n        const cardColumns = screen.getByLabelText('Card columns')\n\n        expect(cardColumns).not.toBeVisible()\n        expect(cardColumns.parentElement).toHaveStyle({ display: 'none' })\n    })\n\n    it('switches visibility without rerendering card columns', () => {\n        const renderCardColumn = vi.spyOn(cardColumnModule, 'CardColumn')\n        renderCardView()\n        const cardColumns = screen.getByLabelText('Card columns')\n        renderCardColumn.mockClear()\n\n        act(() => workspaceViewService.setViewMode('text'))\n        act(() => workspaceViewService.setViewMode('cards'))\n\n        expect(screen.getByLabelText('Card columns')).toBe(cardColumns)\n        expect(renderCardColumn).not.toHaveBeenCalled()\n    })\n\n    it('groups cards into a column per status with id and title', () => {\n        renderCardView()\n\n        expect(screen.getByText('todo')).toBeInTheDocument()\n        expect(screen.getByText('done')).toBeInTheDocument()\n        expect(screen.getByText('F-1')).toBeInTheDocument()\n        expect(screen.getByText('First')).toBeInTheDocument()\n    })\n\n    it('lets desktop columns flex between their minimum and maximum widths', () => {\n        renderCardView()\n\n        const columnStyle = window.getComputedStyle(screen.getByLabelText('todo column'))\n\n        expect(columnStyle.flexGrow).toBe('1')\n        expect(columnStyle.minWidth).toBe('200px')\n        expect(columnStyle.maxWidth).toBe('320px')\n    })\n\n    it('renders both edge scroll zones only on mobile', () => {\n        renderCardView()\n\n        expect(screen.queryByTestId('left-card-scroll-zone')).not.toBeInTheDocument()\n        expect(screen.queryByTestId('right-card-scroll-zone')).not.toBeInTheDocument()\n\n        cleanup()\n        renderCardView({ isMobile: true })\n\n        expect(screen.getByTestId('left-card-scroll-zone')).toBeInTheDocument()\n        expect(screen.getByTestId('right-card-scroll-zone')).toBeInTheDocument()\n    })\n\n    it('scrolls card columns in both directions from either mobile edge and stops on pointer up', () => {\n        renderCardView({ isMobile: true })\n        const cardColumns = screen.getByLabelText('Card columns')\n        const leftZone = screen.getByTestId('left-card-scroll-zone')\n        const rightZone = screen.getByTestId('right-card-scroll-zone')\n        cardColumns.scrollTop = 100\n\n        fireEvent.pointerDown(leftZone, { clientY: 100, pointerId: 1 })\n        fireEvent.pointerMove(leftZone, { clientY: 70, pointerId: 1 })\n        expect(cardColumns.scrollTop).toBe(130)\n\n        fireEvent.pointerUp(leftZone, { pointerId: 1 })\n        fireEvent.pointerMove(leftZone, { clientY: 40, pointerId: 1 })\n        expect(cardColumns.scrollTop).toBe(130)\n\n        fireEvent.pointerDown(rightZone, { clientY: 50, pointerId: 2 })\n        fireEvent.pointerMove(rightZone, { clientY: 80, pointerId: 2 })\n        expect(cardColumns.scrollTop).toBe(100)\n    })\n\n    it('stops edge scrolling on pointer cancellation and uses native scroll boundaries', () => {\n        renderCardView({ isMobile: true })\n        const cardColumns = screen.getByLabelText('Card columns')\n        const leftZone = screen.getByTestId('left-card-scroll-zone')\n        const rightZone = screen.getByTestId('right-card-scroll-zone')\n        let scrollTop = 0\n        Object.defineProperty(cardColumns, 'scrollTop', {\n            configurable: true,\n            get: () => scrollTop,\n            set: (value: number) => {\n                scrollTop = Math.max(0, Math.min(200, value))\n            },\n        })\n\n        fireEvent.pointerDown(leftZone, { clientY: 100, pointerId: 1 })\n        fireEvent.pointerMove(leftZone, { clientY: 130, pointerId: 1 })\n        expect(cardColumns.scrollTop).toBe(0)\n\n        fireEvent.pointerCancel(leftZone, { pointerId: 1 })\n        fireEvent.pointerMove(leftZone, { clientY: 70, pointerId: 1 })\n        expect(cardColumns.scrollTop).toBe(0)\n\n        cardColumns.scrollTop = 200\n        fireEvent.pointerDown(rightZone, { clientY: 100, pointerId: 2 })\n        fireEvent.pointerMove(rightZone, { clientY: 70, pointerId: 2 })\n        expect(cardColumns.scrollTop).toBe(200)\n    })\n\n    it('keeps edge gestures away from cards and preserves card interaction outside the zones', () => {\n        renderCardView({ isMobile: true })\n        const leftZone = screen.getByTestId('left-card-scroll-zone')\n\n        fireEvent.pointerDown(leftZone, { clientY: 100, pointerId: 1 })\n        fireEvent.pointerMove(leftZone, { clientY: 70, pointerId: 1 })\n        fireEvent.pointerUp(leftZone, { pointerId: 1 })\n\n        expect(cardDragDropService.getOverlaySnapshot().cardPath).toBeNull()\n        expect(screen.queryByRole('dialog')).not.toBeInTheDocument()\n\n        fireEvent.click(screen.getByRole('button', { name: 'Drag F-1' }))\n        expect(screen.getByRole('dialog')).toBeInTheDocument()\n    })\n\n    it('shows always-visible columns without cards and hides other empty columns in config order', () => {\n        renderCardView({\n            states: [\n            